export const getDownloadProjectFileUrl = (projectId: string,
    params: DownloadProjectFileParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/mtech/projects/${projectId}/files/download?${stringifiedParams}` : `/api/mtech/projects/${projectId}/files/download`
}

